/** Framework-aware remediation patterns sourced from the 23 playbook; these are not automatic patches. */
data class WebsiteRemediationRecipeV1(
    val sectionId: String,
    val title: String,
    val triggerCwes: Set<String>,
    val triggerTerms: Set<String>,
    val rootCausePattern: String,
    val immediateContainment: String,
    val permanentFix: String,
    val verification: String,
    val regressionTests: List<String>,
    val stagingValidation: String,
    val rollback: String,
    val deploymentMonitoring: String,
    val downtimeRisk: String,
    val ownerRole: String
)

