    fun resolve(finding: Finding): WebsiteRemediationGuidanceV1 {
        val id = finding.id.uppercase(Locale.ROOT)
        val text = (finding.title + " " + finding.description + " " + finding.remediation).lowercase(Locale.ROOT)
        val preferred = when {
            id.startsWith("SG-WP-") || text.contains("wp-config") || text.contains("wordpress") -> recipes.first { it.sectionId == "WP-10" }
            id.contains("WC-") || text.contains("woocommerce") || text.contains("payment callback") -> recipes.first { it.sectionId == "WP-11" }
            else -> recipes.firstOrNull { matches(it, finding) } ?: recipes.last()
        }
        val recipe = preferred
        return WebsiteRemediationGuidanceV1(
            recipe.sectionId, recipe.title, recipe.rootCausePattern, recipe.immediateContainment,
            recipe.permanentFix, recipe.verification, recipe.regressionTests, recipe.stagingValidation,
            recipe.rollback, recipe.deploymentMonitoring, recipe.downtimeRisk, recipe.ownerRole
        )
    }

    private fun matches(recipe: WebsiteRemediationRecipeV1, finding: Finding): Boolean {
        val cwe = finding.cwe.uppercase(Locale.ROOT).replace(" ", "")
        val id = finding.id.uppercase(Locale.ROOT)
        val text = (finding.title + " " + finding.description + " " + finding.remediation).lowercase(Locale.ROOT)
        if (recipe.sectionId == "WP-14") return false
        if (recipe.sectionId == "WP-10" && (id.startsWith("SG-WP-") || text.contains("wordpress") || text.contains("wp-config"))) return true
        if (recipe.sectionId == "WP-11" && (id.contains("WC-") || text.contains("woocommerce") || text.contains("payment callback"))) return true
        return cwe in recipe.triggerCwes || recipe.triggerTerms.any { text.contains(it) || id.lowercase(Locale.ROOT).contains(it.replace(" ", "")) }
    }
}
